// Prepara la pasada: carga o crea la cuenta de prueba y entrega la lista de pares, uno por item.
const REINICIAR_CUENTA = false;   // pon true UNA vez para borrar la cuenta y empezar de cero; luego vuelve a false
const REVISION_DEL_DIARIO_HECHA = false;   // pon true UNA vez cuando hayas revisado el diario tras 5 pérdidas (hasta entonces el Agente 3 no abre nada); luego vuelve a false
const CAPITAL_INICIAL = 10000;    // (mío) dólares de la cuenta de prueba
const PARES = [
  'EUR/USD',  // 21,2 % del volumen mundial de divisas (BIS, 2025)
  'USD/JPY',  // 14,3 %
  'USD/CNY',  // 8,1 %  (puede no tener datos de 5 min en TwelveData)
  'GBP/USD',  // 7,6 %
  'USD/CAD',  // 5,3 %
  'AUD/USD',  // 4,9 %
  'USD/CHF',  // 4,9 %
  'BTC/USD'   // sigue aquí para comparar; quítalo cuando exista el agente solo de cripto
];

const sd = $getWorkflowStaticData('global');
if (REINICIAR_CUENTA || !sd.estado) { sd.estado = { capital: CAPITAL_INICIAL }; sd.meta = { pasadas: 0 }; }
sd.meta = sd.meta ?? { pasadas: 0 };
if (REVISION_DEL_DIARIO_HECHA) sd.estado.perdidasDesdeRevision = 0;   // reinicia el contador de pérdidas sin revisar
sd.meta.pasadas += 1;
sd.meta.ultimaPasada = new Date().toISOString();
sd.bandeja = null;

const vistos = new Set();
return PARES
  .map(p => String(p).trim().toUpperCase())
  .filter(p => p && !vistos.has(p) && vistos.add(p))
  .map(symbol => ({ json: { symbol } }));

// Anota qué par se está procesando. La "bandeja" es un cajón temporal dentro del workflow
// que lleva los datos de este par de un nodo al siguiente sin depender de enlaces entre nodos.
const sd = $getWorkflowStaticData('global');
const item = $input.first().json;
sd.bandeja = { simbolo: String(item.symbol).toUpperCase(), avisos: [] };
return [{ json: item }];

// Guarda las velas y su antigüedad en la bandeja y deja pasar la salida del Agente 1 sin cambios.
const sd = $getWorkflowStaticData('global');
const b = sd.bandeja ?? { simbolo: null, avisos: [] };
const r = $input.first().json ?? {};
const mensaje = e => (typeof e === 'string' ? e : (e?.message ?? JSON.stringify(e)));

if (r.error) {
  b.datos = { ok: false, errores: [`El Agente 1 falló: ${mensaje(r.error)}`] };
  sd.bandeja = b;
  return [{ json: { ok: false, ticker: b.simbolo, errors: b.datos.errores } }];
}
b.candles5m = Array.isArray(r.candles5m) ? r.candles5m : [];
b.edadUltimaVelaMin = typeof r.lastCandleAgeMin === 'number' ? r.lastCandleAgeMin : null;
b.datos = { ok: r.ok === true, errores: r.errors ?? [] };
sd.bandeja = b;
return [{ json: r }];

// ================================================================
// Agente 2 · Estrategia
// Libro: "Day trading", Oliver Vélez y Greg Capra (Deusto, 2005).
// Usa solo precios (sin noticias ni volumen). Propone solo entradas LARGAS
// con la compra clave (libro, pp. 410-412).
// (libro) = cifra o regla del libro, con página.
// (mío)   = valor de partida para calibrar con historial; el libro no lo fija.
// ================================================================

const entrada = $input.first().json;

// ---------- PARÁMETROS: puedes editarlos aquí ----------
const PARAMETROS = {
  plazosEntrada: ['5min', '15min'],
  mediasPorPlazo: {                       // (libro, p. 514)
    '5min': [20, 200],
    '15min': [20, 200],
    '1day': [10, 20, 50, 100, 200]
  },
  periodosATR: 14,                        // (mío)

  // Compra clave (libro, pp. 410-412)
  ventanaNuevoMaximo: 20,                 // (mío) "nuevo máximo" = el mayor de las últimas 20 barras
  maxBarrasDesdeMaximo: 8,                // (libro)
  minBarrasMaximosBajos: 3,               // (libro)

  // Distancias en múltiplos del ATR (el libro usa 1/16 y 1/8 de dólar)
  holguraEntradaATR: 0.05,                // (mío) por encima del máximo de la barra anterior
  holguraStopATR: 0.10,                   // (mío) por debajo del mínimo que sirve de stop
  perseguirMaxATR: 0.25,                  // (mío) si el precio ya se alejó más de esto del disparo, no se persigue
  riesgoMaxATR: 1.5,                      // (mío) "demasiado riesgo": el libro no da cifra
  objetivoR: 2.5,                         // (mío) los ejemplos del libro dan de 2,3 a 2,7 veces el riesgo
  breakevenR: 1.0,                        // (mío) el libro: de 1 a 1,33 veces el riesgo
  timeStopBarras: { '5min': 24, '15min': 8 }, // (libro, p. 436) de 1 a 2 horas en intradía

  // Herramientas gráficas
  nrbFactor: 0.5, nrbVentana: 10,         // (mío) rango menor que la mitad del rango medio de 10 barras
  cierreCercaFraccion: 0.25,              // (mío) "cerca del máximo/mínimo" = 25 % del rango
  colaFraccionMin: 0.5,                   // (mío) mecha de al menos la mitad del rango
  rbCaidaInicial: 0.4,                    // (mío) movimiento inicial en contra de al menos 40 % del rango
  caidaMin: 3, caidaMax: 5,               // (libro, pp. 344-350)
  pivoteBarras: 3, zonaATR: 0.5,          // (mío) pivotes y zona de soportes/resistencias
  retrocesoMaxBarras: 60,                 // (mío)
  nivelesRetroceso: [0.4, 0.5, 0.6, 1.0], // (libro, pp. 319-324)
  toleranciaRetroceso: 0.05,              // (mío)
  pendienteBarras: 5, pendientePlanaATR: 0.15 // (mío) pendiente de la media de 20
};
const P = { ...PARAMETROS, ...(entrada.parametros ?? {}) };

// Si el Agente 1 no entregó datos buenos, no se opera.
if (entrada.ok === false) {
  return [{ json: { ok: false, motivo: 'El Agente 1 no entregó datos válidos: no se opera.', errors: entrada.errors ?? [] } }];
}

// ---------- Utilidades ----------
const redondear = x => (x === null || x === undefined || !Number.isFinite(x)) ? null : Number(x.toPrecision(8));
const rango = c => c.high - c.low;
const media = arr => arr.reduce((a, b) => a + b, 0) / arr.length;

function smaEn(cierres, n, fin) {                  // media simple de n cierres que terminan en 'fin'
  if (fin + 1 < n || fin < 0) return null;
  let s = 0;
  for (let i = fin - n + 1; i <= fin; i++) s += cierres[i];
  return s / n;
}
function atrEn(velas, n, fin) {                    // media de los rangos verdaderos de las n barras hasta 'fin'
  if (fin < n) return null;
  let s = 0;
  for (let i = fin - n + 1; i <= fin; i++) {
    const previo = velas[i - 1].close;
    s += Math.max(velas[i].high - velas[i].low, Math.abs(velas[i].high - previo), Math.abs(velas[i].low - previo));
  }
  return s / n;
}
function pendienteMedia(cierres, n, fin, atr) {    // 'sube' | 'baja' | 'plana'
  const ahora = smaEn(cierres, n, fin);
  const antes = smaEn(cierres, n, fin - P.pendienteBarras);
  if (ahora === null || antes === null || !(atr > 0)) return null;
  const p = (ahora - antes) / atr;
  return p > P.pendientePlanaATR ? 'sube' : p < -P.pendientePlanaATR ? 'baja' : 'plana';
}

// ---------- Herramientas gráficas (todas sobre la barra i ya cerrada) ----------
// 1. Barra de rango estrecho, NRB (libro, pp. 291-295): rango menor que lo normal,
//    tras varias barras de rango normal o ancho.
function esNRB(v, i) {
  if (i < P.nrbVentana + 3) return false;
  const prom = media(v.slice(i - P.nrbVentana, i).map(rango));
  const estrecha = rango(v[i]) < P.nrbFactor * prom;
  const previasNormales = [1, 2, 3].every(k => rango(v[i - k]) >= P.nrbFactor * prom);
  return estrecha && previasNormales;
}
// 2. Barra reversa, RB (libro, pp. 295-300): movimiento inicial en contra y cierre cerca del extremo opuesto.
function tipoRB(v, i) {
  const c = v[i], r = rango(c);
  if (!(r > 0)) return null;
  if (c.close > c.open && (c.high - c.close) <= P.cierreCercaFraccion * r && (c.open - c.low) >= P.rbCaidaInicial * r) return 'alcista';
  if (c.close < c.open && (c.close - c.low) <= P.cierreCercaFraccion * r && (c.high - c.open) >= P.rbCaidaInicial * r) return 'bajista';
  return null;
}
// 3. Colas (libro, pp. 300-304). Mido la mecha real: en el ejemplo del libro (apertura 30, mínimo 27,
//    cierre 29) la cola de 2 coincide con la mecha inferior. Con velas alcistas, medir del mínimo al cierre
//    contaría también el cuerpo y marcaría casi la mitad de las barras (decisión mía).
function colas(c) {
  const r = rango(c);
  if (!(r > 0)) return { fondo: false, tope: false };
  const mechaInf = Math.min(c.open, c.close) - c.low;
  const mechaSup = c.high - Math.max(c.open, c.close);
  return { fondo: mechaInf >= P.colaFraccionMin * r, tope: mechaSup >= P.colaFraccionMin * r };
}
// 10. Caída de 3 a 5 barras (libro, pp. 344-350): barras bajistas consecutivas hasta la barra i.
function barrasBajistas(v, i) {
  let n = 0;
  for (let k = i; k >= 1; k--) {
    if (v[k].close < v[k - 1].close && v[k].close < v[k].open) n++; else break;
  }
  return n;
}
// 5. Soportes y resistencias (libro, pp. 311-318): pivotes de 'pivoteBarras' barras a cada lado.
function pivotes(v) {
  const k = P.pivoteBarras, altos = [], bajos = [];
  for (let i = k; i <= v.length - 1 - k; i++) {
    let alto = true, bajo = true;
    for (let j = 1; j <= k; j++) {
      if (!(v[i].high > v[i - j].high && v[i].high >= v[i + j].high)) alto = false;
      if (!(v[i].low < v[i - j].low && v[i].low <= v[i + j].low)) bajo = false;
    }
    if (alto) altos.push({ i, precio: v[i].high });
    if (bajo) bajos.push({ i, precio: v[i].low });
  }
  return { altos, bajos };
}
function cercaDeSR(v, i, atr, piv) {
  const zona = P.zonaATR * atr, precio = v[i].close;
  const minimo = Math.min(v[i].low, v[i - 1].low), maximo = Math.max(v[i].high, v[i - 1].high);
  let soporte = null, resistencia = null;
  for (const b of piv.bajos) {
    if (Math.abs(minimo - b.precio) <= zona) {
      const sube = Math.max(...v.slice(b.i + 1, b.i + 11).map(c => c.high)) - b.precio;
      const cand = { precio: redondear(b.precio), tipo: sube >= 2 * atr ? 'soporte mayor' : 'soporte menor' };
      if (!soporte || (cand.tipo === 'soporte mayor' && soporte.tipo !== 'soporte mayor')) soporte = cand;
    }
  }
  for (const a of piv.altos) {                       // una resistencia superada pasa a soporte menor
    if (precio > a.precio && Math.abs(minimo - a.precio) <= zona && !soporte) {
      soporte = { precio: redondear(a.precio), tipo: 'soporte menor (resistencia superada)' };
    }
    if (precio < a.precio && Math.abs(a.precio - maximo) <= zona) resistencia = { precio: redondear(a.precio), tipo: 'resistencia' };
  }
  return { soporte, resistencia };
}
// 6. Retrocesos (libro, pp. 319-324): cuánto del último avance se ha devuelto.
function retroceso(v, i, piv) {
  const ph = piv.altos.at(-1);
  if (!ph || i - ph.i > P.retrocesoMaxBarras) return null;
  const pl = piv.bajos.filter(b => b.i < ph.i).at(-1);
  if (!pl) return null;
  const mov = ph.precio - pl.precio;
  if (!(mov > 0)) return null;
  const pct = (ph.precio - v[i].close) / mov;
  if (pct < 0) return null;
  const cerca = P.nivelesRetroceso.find(n => Math.abs(pct - n) <= P.toleranciaRetroceso) ?? null;
  return { pct: redondear(pct), nivelCercano: cerca, desde: redondear(ph.precio), hasta: redondear(pl.precio) };
}

// ---------- Compra clave (libro, pp. 410-412) ----------
// 1) El valor marcó un nuevo máximo como mucho 8 barras atrás.
// 2) Desde entonces hay 3 o más barras con máximos consecutivos más bajos.
// Entrada: 1/16 a 1/8 por encima del máximo de la barra anterior (aquí, holguraEntradaATR).
// Stop inicial: método de la barra anterior (libro, p. 427) y, si arriesga demasiado,
// método de la barra actual (libro, p. 428).
function compraClave(v, cur, atr, plazo) {
  const p = v.length - 1;                            // barra anterior a la de entrada
  if (p < P.ventanaNuevoMaximo + P.maxBarrasDesdeMaximo) return { estado: 'SIN_SETUP', motivo: 'pocas barras' };

  for (let k = P.minBarrasMaximosBajos; k <= P.maxBarrasDesdeMaximo; k++) {
    const h = p - k;
    const previas = v.slice(h - P.ventanaNuevoMaximo + 1, h);
    if (!previas.every(c => v[h].high > c.high)) continue;          // la barra h no es un nuevo máximo
    let bajando = true;
    for (let j = h + 1; j <= p; j++) if (!(v[j].high < v[j - 1].high)) { bajando = false; break; }
    if (!bajando) continue;

    const disparo = v[p].high + P.holguraEntradaATR * atr;
    const disparada = cur.high >= disparo;
    let estado = disparada ? 'DISPARADA' : 'ARMADA';
    if (disparada && (cur.close - disparo) > P.perseguirMaxATR * atr) estado = 'NO_PERSEGUIR';

    const stopAnterior = v[p].low - P.holguraStopATR * atr;
    const stopActual = disparada ? cur.low - P.holguraStopATR * atr : null;
    const maxRiesgo = P.riesgoMaxATR * atr;
    let stop = stopAnterior, metodoStop = 'barra anterior (libro, p. 427)', valido = true, motivo = null;
    if (disparo - stop > maxRiesgo) {
      if (stopActual !== null && stopActual < disparo && disparo - stopActual <= maxRiesgo) {
        stop = stopActual; metodoStop = 'barra actual (libro, p. 428)';
      } else {
        valido = false;
        motivo = stopActual === null
          ? 'riesgo excesivo con la barra anterior; se reevalúa con la barra actual al dispararse'
          : 'riesgo excesivo con ambos métodos de stop';
      }
    }
    const resultado = {
      estado, valido, motivo,
      nuevoMaximoHaceBarras: k, barrasConMaximosBajos: k,
      regla: 'Compra clave (libro, pp. 410-412)',
      disparo: redondear(disparo)
    };
    if (valido) {
      const R = disparo - stop;
      resultado.plan = {
        entrada: redondear(disparo),
        stop: redondear(stop), metodoStop,
        riesgo: redondear(R), riesgoATR: redondear(R / atr),
        breakeven: redondear(disparo + P.breakevenR * R),
        ventaParcial: { en: redondear(disparo + P.breakevenR * R), fraccion: 0.5 },   // venta incremental (libro, pp. 438-441)
        objetivo: redondear(disparo + P.objetivoR * R),
        timeStopBarras: P.timeStopBarras[plazo] ?? null                              // (libro, p. 436)
      };
    }
    return resultado;
  }
  return { estado: 'SIN_SETUP' };
}

// ---------- Lectura de un plazo ----------
function leerPlazo(plazo, velas) {
  if (!Array.isArray(velas) || velas.length < 40) {
    return { plazo, ok: false, avisos: [`pocas velas (${Array.isArray(velas) ? velas.length : 0})`] };
  }
  const v = velas.slice(0, -1);                       // barras cerradas
  const cur = velas.at(-1);                           // barra en curso
  const i = v.length - 1;
  const atr = atrEn(v, P.periodosATR, i);
  if (!(atr > 0)) return { plazo, ok: false, avisos: ['no se pudo calcular el ATR'] };

  const cierres = v.map(c => c.close);
  const avisos = [];
  const medias = {}, cercaDeMedia = [];
  for (const n of P.mediasPorPlazo[plazo] ?? []) {
    const m = smaEn(cierres, n, i);
    medias['sma' + n] = redondear(m);
    if (m === null) { avisos.push(`faltan velas para la media de ${n}`); continue; }
    if (Math.abs(v[i].close - m) <= P.zonaATR * atr || (v[i].low <= m && m <= v[i].high)) cercaDeMedia.push('SMA' + n);
  }
  const pend20 = pendienteMedia(cierres, 20, i, atr);

  const piv = pivotes(v);
  const sr = cercaDeSR(v, i, atr, piv);
  const retro = retroceso(v, i, piv);
  const nrb = esNRB(v, i);
  const rb = tipoRB(v, i);
  const cola = colas(v[i]);
  const caida = barrasBajistas(v, i);
  const caida3a5 = caida >= P.caidaMin && caida <= P.caidaMax;

  const confluencias = [];
  if (nrb) confluencias.push('barra de rango estrecho');
  if (rb === 'alcista') confluencias.push('barra reversa alcista');
  if (cola.fondo) confluencias.push('cola de fondo');
  if (caida3a5) confluencias.push(`caída de ${caida} barras`);
  if (sr.soporte) confluencias.push(sr.soporte.tipo);
  if (cercaDeMedia.length) confluencias.push('cerca de ' + cercaDeMedia.join(' y '));
  if (retro && retro.nivelCercano !== null) confluencias.push(`retroceso del ${Math.round(retro.nivelCercano * 100)} %`);

  return {
    plazo, ok: true,
    ultimaCerrada: v[i].time, precioActual: cur.close, atr: redondear(atr),
    medias, pendienteSMA20: pend20,
    herramientas: {
      nrb, rb, cola, barrasBajistas: caida, caida3a5,
      soporte: sr.soporte, resistencia: sr.resistencia, retroceso: retro, cercaDeMedia
    },
    compraClave: compraClave(v, cur, atr, plazo),
    confluencias, nConfluencias: confluencias.length,
    avisos
  };
}

// ---------- Contexto diario (no bloquea entradas) ----------
function contextoDiario(velas, precio) {
  if (!Array.isArray(velas) || velas.length < 30) return { ok: false, aviso: 'pocas velas diarias' };
  const v = velas.slice(0, -1), cierres = v.map(c => c.close), fin = v.length - 1;
  const atr = atrEn(v, P.periodosATR, fin);
  const medias = {};
  for (const n of P.mediasPorPlazo['1day']) medias['sma' + n] = redondear(smaEn(cierres, n, fin));
  return {
    ok: true, ultimaCerrada: v[fin].time, medias,
    pendienteSMA20: pendienteMedia(cierres, 20, fin, atr),
    precioSobreSMA200: medias.sma200 === null ? null : precio > medias.sma200
  };
}

// ---------- Resultado ----------
const lecturas = {};
for (const plazo of ['5min', '15min']) {
  const velas = plazo === '5min' ? entrada.candles5m : entrada.candles15m;
  lecturas[plazo] = leerPlazo(plazo, velas);
}
const precioActual = entrada.lastPrice ?? lecturas['5min'].precioActual ?? null;
const diario = contextoDiario(entrada.candles1d, precioActual);

const senales = [];
for (const plazo of P.plazosEntrada) {
  const l = lecturas[plazo];
  const ck = l?.ok ? l.compraClave : null;
  if (ck && ['ARMADA', 'DISPARADA'].includes(ck.estado) && ck.valido) {
    senales.push({
      plazo, tipo: 'COMPRA', estado: ck.estado, regla: ck.regla,
      ...ck.plan, confluencias: l.confluencias, nConfluencias: l.nConfluencias
    });
  }
}
senales.sort((a, b) => b.nConfluencias - a.nConfluencias);
const decision = senales[0] ?? null;

const avisos = [];
for (const plazo of Object.keys(lecturas)) for (const a of lecturas[plazo].avisos ?? []) avisos.push(`${plazo}: ${a}`);
if (!diario.ok) avisos.push(`1day: ${diario.aviso}`);

const resumen = decision
  ? `${decision.plazo}: compra clave ${decision.estado} · entrada ${decision.entrada} · stop ${decision.stop} · objetivo ${decision.objetivo} · ${decision.nConfluencias} confluencia(s)`
  : 'Sin señal de compra clave en 5 min ni 15 min.';

return [{ json: {
  ok: true,
  ticker: entrada.ticker ?? null,
  generadoEn: new Date().toISOString(),
  precioActual: redondear(precioActual),
  resumen,
  decision,
  senales,
  contextoDiario: diario,
  plazos: lecturas,
  avisos
} }];

// Guarda la señal del Agente 2 y prepara la llamada que gestiona las posiciones abiertas de este par.
const sd = $getWorkflowStaticData('global');
const b = sd.bandeja ?? { simbolo: null, avisos: [] };
const r = $input.first().json ?? {};
const mensaje = e => (typeof e === 'string' ? e : (e?.message ?? JSON.stringify(e)));

b.senal = r.error ? { ok: false, motivo: `El Agente 2 falló: ${mensaje(r.error)}`, errors: [] } : r;
const velas = b.simbolo && b.candles5m?.length ? { [b.simbolo]: b.candles5m } : {};
sd.bandeja = b;
return [{ json: { estado: sd.estado, velas } }];

// ================================================================
// Agente 4 · Motor de paper trading (simula las operaciones, no usa dinero ni broker)
// Recibe las órdenes aprobadas por el Agente 3 y las velas nuevas, y gestiona las posiciones:
// entrada, stop, venta de la mitad, stop a equilibrio, objetivo y salida por tiempo.
// No guarda nada por sí mismo: el estado ENTRA y SALE en cada llamada (campo "estado").
// Quien lo llame (el orquestador) es quien lo guarda entre una llamada y la siguiente.
// (libro) = regla del libro "Day trading" (Vélez y Capra), con página.
// (mío)   = supuesto de simulación que debes calibrar.
//
// ENTRADA (un solo item):
//   estado       el estado devuelto por la llamada anterior (si falta, cuenta nueva)
//   ordenes      lista de "orden" aprobadas por el Agente 3 (o "orden" suelta)
//   velas        { "EUR/USD": [ {time, open, high, low, close}, ... ] }  (velas de 5 min)
//                o bien la salida del Agente 1 (ticker + candles5m)
//   ahora        fecha ISO (por defecto, ahora mismo)
//   cuenta       { capital } solo si no hay estado
//   revisionHecha  true si ya revisaste el diario (reinicia el contador de pérdidas)
//   parametros   cualquier parámetro de abajo
// ================================================================

const entrada = $input.first().json ?? {};

// ---------- PARÁMETROS: puedes editarlos aquí ----------
const PARAMETROS = {
  capitalPorDefecto: 10000,                // (mío) cuenta de prueba en dólares
  barraDatosMin: 5,                        // (mío) minutos de cada vela con que se gestionan las posiciones
  minutosPorPlazo: { '5min': 5, '15min': 15, '1h': 60, '1day': 1440 },
  neutralR: 0.05,                          // (mío) una operación entre -0,05 R y +0,05 R no cuenta como racha
  zonaDia: 'UTC',                          // (mío) zona que define cuándo empieza el día para los contadores diarios
  friccionPct: { forex: 0.006, cripto: 0.2, otros: 0.02 },   // (mío) costo de ida y vuelta, % del valor de la posición
  maxFilasDiario: 200
};

// Reglas de la simulación (todas pesimistas, para no ser optimista por accidente):
//  - Solo se usan velas CERRADAS. La vela en curso se procesa cuando cierre.
//  - Si en una misma vela el precio toca el stop y también un nivel a favor, se asume que tocó el stop primero.
//  - Si una vela abre más allá del stop, la salida es al precio de apertura (hueco), no al stop.
//  - Tras vender la mitad y subir el stop a equilibrio, si esa misma vela vuelve al precio de entrada, se asume que salió ahí.
//  - Una orden a mercado entra al precio de referencia; una orden pendiente entra al precio de la orden (o a la apertura si hay hueco).
//  - La posición se gestiona desde la primera vela que abre después de la entrada.

// ---------- Utilidades ----------
const CRIPTO = new Set(['BTC', 'ETH', 'SOL', 'XRP', 'LTC', 'BNB', 'ADA', 'DOGE']);
const redondear = (x, d = 8) => (Number.isFinite(x) ? Math.round(x * 10 ** d) / 10 ** d : null);
const esNumero = x => typeof x === 'number' && Number.isFinite(x);
const num = (x, def) => (x !== null && x !== '' && x !== undefined && Number.isFinite(Number(x)) ? Number(x) : def);
const arreglo = x => (Array.isArray(x) ? x : []);
const iso = ms => new Date(ms).toISOString();
const mayus = s => String(s ?? '').toUpperCase();

function partesDelPar(simbolo) {
  const m = /^([A-Z]{3,5})\/([A-Z]{3,5})$/.exec(mayus(simbolo));
  return m ? { base: m[1], cotizada: m[2] } : null;
}
const claseActivo = s => { const p = partesDelPar(s); return p ? (CRIPTO.has(p.base) ? 'cripto' : 'forex') : 'otros'; };
const pasoUnidades = s => (claseActivo(s) === 'cripto' ? 1e-4 : 1);

// ---------- Preparación ----------
const P = { ...PARAMETROS, ...(entrada.parametros ?? {}), friccionPct: { ...PARAMETROS.friccionPct, ...(entrada.parametros?.friccionPct ?? {}) } };
const ahora = entrada.ahora ? new Date(entrada.ahora) : new Date();
if (Number.isNaN(ahora.getTime())) throw new Error('El campo "ahora" no es una fecha válida.');
const ahoraMs = ahora.getTime();
const barraMs = P.barraDatosMin * 60000;

const E0 = JSON.parse(JSON.stringify(entrada.estado ?? {}));
const E = {
  capital: num(E0.capital, num(entrada.cuenta?.capital, P.capitalPorDefecto)),
  posiciones: arreglo(E0.posiciones),
  ordenesPendientes: arreglo(E0.ordenesPendientes),
  ultimaVela: E0.ultimaVela && typeof E0.ultimaVela === 'object' ? E0.ultimaVela : {},
  dia: E0.dia ?? null,
  operacionesHoy: num(E0.operacionesHoy, 0), pnlHoyR: num(E0.pnlHoyR, 0), maxPnlHoyR: num(E0.maxPnlHoyR, 0),
  gananciasSeguidas: num(E0.gananciasSeguidas, 0), perdidasSeguidas: num(E0.perdidasSeguidas, 0),
  rachaGanadoraPrevia: num(E0.rachaGanadoraPrevia, 0), perdidasDesdeRevision: num(E0.perdidasDesdeRevision, 0),
  siguienteId: num(E0.siguienteId, 1),
  diario: arreglo(E0.diario)
};
if (!(E.capital > 0)) throw new Error('El capital debe ser mayor que cero.');

let formatoDia;
try {
  formatoDia = new Intl.DateTimeFormat('en-CA', { timeZone: P.zonaDia, year: 'numeric', month: '2-digit', day: '2-digit' });
  formatoDia.format(ahora);
} catch (e) { throw new Error(`Zona horaria no válida: ${P.zonaDia}`); }
const diaDe = ms => formatoDia.format(new Date(ms));
// Día nuevo: se reinician los contadores diarios (las rachas siguen).
// El día de cada hecho es el de su vela, no el de la llamada: así partir las velas en varias llamadas da lo mismo.
function avanzarDia(ms) {
  const k = diaDe(ms);
  if (k > E.dia) { E.dia = k; E.operacionesHoy = 0; E.pnlHoyR = 0; E.maxPnlHoyR = 0; }
}
if (E.dia === null) E.dia = diaDe(ahoraMs);
if (entrada.revisionHecha === true) E.perdidasDesdeRevision = 0;

const eventos = [], diarioNuevo = [], avisos = [];

// Velas por símbolo: solo cerradas, ordenadas, sin datos inválidos
function limpiar(v) {
  return arreglo(v).map(c => ({ ...c, t: Date.parse(c.time), open: Number(c.open), high: Number(c.high), low: Number(c.low), close: Number(c.close) }))
    .filter(c => Number.isFinite(c.t) && [c.open, c.high, c.low, c.close].every(Number.isFinite) && c.high >= c.low)
    .sort((a, b) => a.t - b.t);
}
const velasPorSimbolo = {};
if (entrada.velas && typeof entrada.velas === 'object') for (const [s, v] of Object.entries(entrada.velas)) velasPorSimbolo[mayus(s)] = limpiar(v);
if (entrada.ticker && Array.isArray(entrada.candles5m) && !velasPorSimbolo[mayus(entrada.ticker)]) velasPorSimbolo[mayus(entrada.ticker)] = limpiar(entrada.candles5m);

// ---------- Contabilidad ----------
function pnlBruto(pos, precio, unidades) {
  const par = partesDelPar(pos.simbolo);
  const dif = precio - pos.entrada;                                  // solo posiciones largas
  return par && par.base === 'USD' ? (dif * unidades) / precio : dif * unidades;
}
function friccion(pos, unidades) {
  const par = partesDelPar(pos.simbolo);
  const valor = par && par.base === 'USD' ? unidades : unidades * pos.entrada;
  return valor * (P.friccionPct[claseActivo(pos.simbolo)] ?? P.friccionPct.otros) / 100;
}

function cerrarParte(pos, precio, unidades, tipo, tms) {
  const costo = friccion(pos, unidades);
  const pnl = pnlBruto(pos, precio, unidades) - costo;
  pos.realizadoUSD = pos.realizadoUSD + pnl;
  pos.unidadesRestantes = redondear(pos.unidadesRestantes - unidades, 6);
  E.capital = redondear(E.capital + pnl, 6);
  eventos.push({ tipo, id: pos.id, simbolo: pos.simbolo, tiempo: iso(tms), precio: redondear(precio), unidades: redondear(unidades, 6),
    pnlUSD: redondear(pnl, 6), costoUSD: redondear(costo, 6) });
}

function cerrarTodo(pos, precio, tipo, tms) {
  cerrarParte(pos, precio, pos.unidadesRestantes, tipo, tms);
  avanzarDia(tms);
  const R = pos.riesgoDinero > 0 ? pos.realizadoUSD / pos.riesgoDinero : 0;
  E.pnlHoyR += R; E.maxPnlHoyR = Math.max(E.maxPnlHoyR, E.pnlHoyR);
  if (R > P.neutralR) {
    E.gananciasSeguidas += 1; E.perdidasSeguidas = 0; E.rachaGanadoraPrevia = 0;
  } else if (R < -P.neutralR) {
    if (E.perdidasSeguidas === 0) E.rachaGanadoraPrevia = E.gananciasSeguidas;
    E.gananciasSeguidas = 0; E.perdidasSeguidas += 1; E.perdidasDesdeRevision += 1;
  }
  const fila = {
    id: pos.id, simbolo: pos.simbolo, plazo: pos.plazo, lado: 'COMPRA', regla: pos.regla,
    apertura: pos.abiertaEn, cierre: iso(tms), duracionMin: Math.round((tms - Date.parse(pos.abiertaEn)) / 60000),
    entrada: pos.entrada, stopInicial: pos.stopInicial, objetivo: pos.objetivo, salidaFinal: redondear(precio),
    unidades: pos.unidades, motivoSalida: tipo, pnlUSD: redondear(pos.realizadoUSD, 4), R: redondear(R, 3),
    cumpleReglas: true                       // el motor solo ejecuta lo que el Agente 3 aprobó (libro, p. 173)
  };
  diarioNuevo.push(fila);
  E.diario.push(fila);
  if (E.diario.length > P.maxFilasDiario) E.diario.splice(0, E.diario.length - P.maxFilasDiario);
  E.posiciones = E.posiciones.filter(p => p.id !== pos.id);
}

// ---------- Gestión de una vela cerrada ----------
function unidadesParciales(pos) {
  const paso = pasoUnidades(pos.simbolo), f = pos.ventaParcial?.fraccion ?? 0;
  const u = Math.floor((pos.unidades * f) / paso + 1e-9) * paso;
  return u >= paso && u < pos.unidadesRestantes ? redondear(u, 4) : 0;
}

function gestionarBarra(pos, b) {
  pos.ultimaBarraGestionada = b.t;
  // 1. Stop (el stop solo sube, nunca se aleja: libro, pp. 157, 179)
  if (b.low <= pos.stop) {
    return cerrarTodo(pos, Math.min(pos.stop, b.open), pos.stopEnEquilibrio ? 'STOP_EQUILIBRIO' : 'STOP', b.t);
  }
  // 2. Venta de la mitad y stop a equilibrio (libro, pp. 431-433, 438-441)
  const nivel = pos.ventaParcial?.en ?? pos.nivelEquilibrio;
  if (!pos.parcialHecha && esNumero(nivel) && b.high >= nivel) {
    pos.parcialHecha = true;
    const vender = unidadesParciales(pos);
    if (vender > 0) cerrarParte(pos, Math.max(nivel, b.open), vender, 'PARCIAL', b.t);
    if (pos.entrada > pos.stop) {
      pos.stop = pos.entrada; pos.stopEnEquilibrio = true;
      eventos.push({ tipo: 'STOP_A_EQUILIBRIO', id: pos.id, simbolo: pos.simbolo, tiempo: iso(b.t), precio: redondear(pos.stop) });
    }
    if (b.low <= pos.stop) return cerrarTodo(pos, pos.stop, 'STOP_EQUILIBRIO', b.t);
  }
  // 3. Objetivo
  if (b.high >= pos.objetivo) return cerrarTodo(pos, Math.max(pos.objetivo, b.open), 'OBJETIVO', b.t);
  // 4. Salida por tiempo (libro, p. 436)
  const plazoMs = (P.minutosPorPlazo[pos.plazo] ?? P.barraDatosMin) * 60000;
  if (pos.timeStopBarras && (b.t + barraMs) - Date.parse(pos.abiertaEn) >= pos.timeStopBarras * plazoMs) {
    return cerrarTodo(pos, b.close, 'TIEMPO', b.t + barraMs);
  }
}

function abrirPosicion(o, precio, tms, detalle) {
  const pos = {
    id: `T${E.siguienteId++}`, simbolo: mayus(o.simbolo), plazo: o.plazo ?? null, lado: 'COMPRA',
    unidades: o.unidades, unidadesRestantes: o.unidades,
    entrada: redondear(precio), entradaPlan: o.entrada, stop: o.stop, stopInicial: o.stop, objetivo: o.objetivo,
    ventaParcial: o.gestion?.ventaParcial ?? null, nivelEquilibrio: o.gestion?.stopAEquilibrio?.cuando ?? null,
    parcialHecha: false, stopEnEquilibrio: false, timeStopBarras: o.gestion?.timeStopBarras ?? null,
    abiertaEn: iso(tms), regla: o.regla ?? null, metodoStop: o.metodoStop ?? null,
    riesgoDinero: o.riesgoDinero, realizadoUSD: 0, ultimaBarraGestionada: null
  };
  E.posiciones.push(pos);
  avanzarDia(tms);
  E.operacionesHoy += 1;
  eventos.push({ tipo: 'ENTRADA', id: pos.id, simbolo: pos.simbolo, tiempo: iso(tms), precio: pos.entrada, unidades: pos.unidades, detalle });
  return pos;
}

// ---------- 1) Velas cerradas desde la última llamada (en orden cronológico entre todos los símbolos) ----------
const trabajo = [];
for (const [sim, velas] of Object.entries(velasPorSimbolo)) {
  const ult = E.ultimaVela[sim] ? Date.parse(E.ultimaVela[sim]) : -Infinity;
  const nuevas = velas.filter(b => b.t > ult && b.t + barraMs <= ahoraMs);
  for (const b of nuevas) trabajo.push({ sim, b });
  if (nuevas.length) E.ultimaVela[sim] = iso(nuevas.at(-1).t);
}
trabajo.sort((x, y) => x.b.t - y.b.t || (x.sim < y.sim ? -1 : 1));
for (const { sim, b } of trabajo) {
  for (const ord of E.ordenesPendientes.filter(o => o.simbolo === sim)) {
    if (b.t >= Date.parse(ord.venceEn)) {
      E.ordenesPendientes = E.ordenesPendientes.filter(o => o.id !== ord.id);
      eventos.push({ tipo: 'ORDEN_VENCIDA', id: ord.id, simbolo: sim, tiempo: iso(b.t), detalle: 'no se activó a tiempo' });
    } else if (b.t >= Date.parse(ord.creadaEn) && b.high >= ord.entrada) {
      E.ordenesPendientes = E.ordenesPendientes.filter(o => o.id !== ord.id);
      const pos = abrirPosicion(ord, Math.max(ord.entrada, b.open), b.t, 'orden stop activada');
      gestionarBarra(pos, b);
    }
  }
  for (const pos of [...E.posiciones.filter(p => p.simbolo === sim)]) {
    if (b.t >= Date.parse(pos.abiertaEn) && !(pos.ultimaBarraGestionada >= b.t)) gestionarBarra(pos, b);
  }
}
for (const s of new Set([...E.posiciones, ...E.ordenesPendientes].map(x => x.simbolo))) {
  if (!velasPorSimbolo[s]) avisos.push(`No llegaron velas de ${s}: su posición u orden no se gestionó en esta llamada.`);
}

// ---------- 2) Órdenes nuevas del Agente 3 ----------
const nuevasOrdenes = [...arreglo(entrada.ordenes), ...(entrada.orden ? [entrada.orden] : [])];
for (const o of nuevasOrdenes) {
  const sim = mayus(o?.simbolo);
  const rechazar = detalle => eventos.push({ tipo: 'ORDEN_RECHAZADA', simbolo: sim || null, tiempo: iso(ahoraMs), detalle });
  const faltan = ['entrada', 'stop', 'objetivo', 'unidades', 'riesgoDinero'].filter(k => !esNumero(o?.[k]));
  if (!sim || faltan.length) { rechazar(`orden incompleta (falta: ${faltan.join(', ') || 'símbolo'})`); continue; }
  if (!(o.stop > 0 && o.stop < o.entrada && o.entrada < o.objetivo && o.unidades > 0)) { rechazar('orden con precios o unidades sin sentido'); continue; }
  if ([...E.posiciones, ...E.ordenesPendientes].some(x => x.simbolo === sim)) { rechazar('ya hay una posición u orden en este símbolo (no se promedia)'); continue; }
  if (o.tipo === 'MERCADO') {
    const precio = esNumero(o.precioReferencia) ? o.precioReferencia : o.entrada;
    if (precio <= o.stop) { rechazar('el precio actual ya está por debajo del stop'); continue; }
    abrirPosicion(o, precio, ahoraMs, 'a mercado');
  } else if (o.tipo === 'STOP_PENDIENTE') {
    const plazoMs = (P.minutosPorPlazo[o.plazo] ?? P.barraDatosMin) * 60000;
    const id = `T${E.siguienteId++}`;
    E.ordenesPendientes.push({ ...o, id, simbolo: sim, creadaEn: iso(ahoraMs), venceEn: iso(ahoraMs + (o.venceEnBarras ?? 3) * plazoMs) });
    eventos.push({ tipo: 'ORDEN_PENDIENTE', id, simbolo: sim, tiempo: iso(ahoraMs), precio: o.entrada, unidades: o.unidades, detalle: 'espera a que el precio supere la entrada' });
  } else {
    rechazar(`tipo de orden desconocido (${o.tipo})`);
  }
}

// ---------- Salida ----------
avanzarDia(ahoraMs);
E.capital = redondear(E.capital, 6);
const ultimoPrecio = s => velasPorSimbolo[s]?.at(-1)?.close ?? null;
const abiertas = E.posiciones.map(p => {
  const px = ultimoPrecio(p.simbolo);
  return { id: p.id, simbolo: p.simbolo, entrada: p.entrada, stop: p.stop, objetivo: p.objetivo, unidadesRestantes: p.unidadesRestantes,
    parcialHecha: p.parcialHecha, stopEnEquilibrio: p.stopEnEquilibrio, abiertaEn: p.abiertaEn,
    pnlNoRealizadoUSD: px === null ? null : redondear(pnlBruto(p, px, p.unidadesRestantes), 4) };
});
const pendientes = E.ordenesPendientes.map(o => ({ id: o.id, simbolo: o.simbolo, entrada: o.entrada, venceEn: o.venceEn }));

const lineas = eventos.map(e => `${e.tipo} ${e.simbolo ?? ''}${e.precio !== undefined ? ' @' + e.precio : ''}${e.pnlUSD !== undefined ? ` (${e.pnlUSD >= 0 ? '+' : ''}${e.pnlUSD} USD)` : ''}${e.tipo === 'ORDEN_RECHAZADA' ? ': ' + e.detalle : ''}`);
const resumen = `${eventos.length ? lineas.join(' · ') : 'Sin eventos.'} | capital ${E.capital} USD | abiertas ${abiertas.length} | pendientes ${pendientes.length} | día: ${E.operacionesHoy} entradas, ${redondear(E.pnlHoyR, 2)} R`;

return [{ json: { ok: true, generadoEn: iso(ahoraMs), resumen, eventos, diarioNuevo, abiertas, pendientes, avisos, estado: E } }];

// Guarda el estado tras gestionar las posiciones y prepara la entrada del Agente 3 (señal + cuenta + estado).
const sd = $getWorkflowStaticData('global');
const b = sd.bandeja ?? { simbolo: null, avisos: [] };
const g = $input.first().json ?? {};
const mensaje = e => (typeof e === 'string' ? e : (e?.message ?? JSON.stringify(e)));

if (g.error) {
  b.avisos.push(`Falló la gestión de posiciones: ${mensaje(g.error)}`);
  b.eventosGestion = [];
} else {
  sd.estado = g.estado;
  b.eventosGestion = g.eventos ?? [];
  for (const a of g.avisos ?? []) if (b.simbolo && a.includes(b.simbolo)) b.avisos.push(a);   // solo avisos de este par
}
delete b.candles5m;      // ya no hacen falta; así no se guardan de más
sd.bandeja = b;

const senal = b.senal ?? { ok: false };
return [{ json: { ...senal, edadUltimaVelaMin: b.edadUltimaVelaMin ?? null, cuenta: { capital: sd.estado.capital }, estado: sd.estado } }];

// ================================================================
// Agente 3 · Riesgo y conducta
// Recibe la señal del Agente 2 y decide si se convierte en orden y de qué tamaño.
// No ejecuta nada. No guarda estado: el estado del día lo lleva el Agente 4 y se lo pasa.
// (libro) = regla o cifra del libro "Day trading" (Vélez y Capra), con página.
// (mío)   = valor de partida para calibrar con historial; el libro no lo fija.
//
// ENTRADA (un solo item): la salida del Agente 2 más estos campos opcionales:
//   edadUltimaVelaMin  minutos de antigüedad de la última vela (viene del Agente 1)
//   cuenta             { capital }  (por defecto, la cuenta de prueba)
//   estado             lo que lleva el Agente 4 (ver ESTADO_VACIO)
//   parametros         cualquier parámetro de abajo para sobrescribirlo
//   ahora              fecha ISO (solo para pruebas)
// ================================================================

const entrada = $input.first().json ?? {};

// ---------- PARÁMETROS: puedes editarlos aquí ----------
const PARAMETROS = {
  capitalPorDefecto: 10000,               // (mío) cuenta de prueba en dólares
  riesgoPorOperacionPct: 0.5,             // (mío) % del capital que se arriesga en cada operación
  nocionalMaxSobreCapital: 10,            // (mío) valor de la posición / capital, tope contra stops muy cortos

  // Límites del día
  maxOperacionesDia: 4,                   // (libro, ejemplo de 4 operaciones al día, p. 170)
  maxOperacionesDiaTrasRacha: 2,          // (libro, ejemplo de bajar de 4 a 2, p. 170)
  perdidaDiariaMaxR: 3,                   // (mío) se para el día al perder 3 veces el riesgo inicial
  protegerGananciaDesdeR: 2,              // (mío) desde esta ganancia del día se vigila que no se devuelva
  fraccionDevueltaMax: 0.5,               // (mío) se para si se devuelve esta fracción del máximo del día (libro, p. 202)

  // Posiciones
  maxPosicionesAbiertas: 3,               // (mío) incluye órdenes pendientes
  maxPosicionesPorSimbolo: 1,             // (libro) no promediar a la baja ni añadir (pp. 91, 104, 246)
  maxPosicionesPorDivisa: 2,              // (mío) evita acumular la misma apuesta (p. ej. cinco pares contra el dólar)

  // Rachas (libro, pp. 170 y 203)
  gananciasParaReducir: 4,                // (libro) "tras 4 o 5 ganadoras seguidas"
  factorTrasRacha: 0.5,                   // (libro) reducir el lote a la mitad
  perdidasParaReducirFrecuencia: 2,       // (libro) 2 pérdidas seguidas tras una racha larga
  rachaLargaMin: 4,                       // (libro)

  // Diario (libro, pp. 124 y 193-195)
  perdidasParaRevisar: 5,                 // (libro) con 5 pérdidas hay que revisar el diario

  // Calidad de la señal y de los datos
  edadMaximaDatosMin: 15,                 // (mío) la última vela de 5 min no puede ser más vieja
  minConfluencias: 0,                     // (mío) 0 = no filtrar; el libro pide actuar sin esperar más confirmaciones (pp. 215-217)

  // Órdenes pendientes
  vencimientoOrdenBarras: 3,              // (mío) una orden armada que no se activa en N barras se cancela

  // Horario. El libro trabaja con la sesión de Nueva York y solo para acciones (pp. 223-224, 514-515).
  // modo: 'desactivado' | 'ny_libro' | 'personalizado'
  horario: {
    modo: 'desactivado',                  // (mío) hasta decidir con historial qué horas usar en divisas y cripto
    zona: 'America/New_York',
    ventanas: [['09:35', '11:15'], ['14:15', '16:00']],   // (libro, p. 515) menor riesgo
    dias: [1, 2, 3, 4, 5]                 // 1 = lunes ... 7 = domingo
  }
};

const ESTADO_VACIO = {
  operacionesHoy: 0,          // entradas ejecutadas hoy
  pnlHoyR: 0,                 // resultado del día en múltiplos del riesgo inicial (R)
  maxPnlHoyR: 0,              // el mayor resultado del día alcanzado hasta ahora
  gananciasSeguidas: 0,
  perdidasSeguidas: 0,
  rachaGanadoraPrevia: 0,     // ganadoras seguidas que había antes de la racha perdedora actual
  perdidasDesdeRevision: 0,   // pérdidas desde la última revisión del diario
  posiciones: [],             // [{ simbolo, lado }]
  ordenesPendientes: []       // [{ simbolo, lado }]
};

// ---------- Utilidades ----------
const CRIPTO = new Set(['BTC', 'ETH', 'SOL', 'XRP', 'LTC', 'BNB', 'ADA', 'DOGE']);
const redondear = (x, d = 8) => (Number.isFinite(x) ? Math.round(x * 10 ** d) / 10 ** d : null);
const esNumero = x => typeof x === 'number' && Number.isFinite(x);
const aNumero = (x, porDefecto) => (esNumero(Number(x)) && x !== null && x !== '' ? Number(x) : porDefecto);

function partesDelPar(simbolo) {
  const m = /^([A-Z]{3,5})\/([A-Z]{3,5})$/.exec(String(simbolo ?? '').toUpperCase());
  return m ? { base: m[1], cotizada: m[2] } : null;
}
// Dólares que gana o pierde una unidad cuando el precio se mueve 1.0
function dolaresPorUnidadYPrecio(par, precio) {
  if (!par || par.cotizada === 'USD') return 1;      // acción o par cotizado en dólares
  if (par.base === 'USD') return 1 / precio;         // USD/JPY, USD/CAD...
  return null;                                       // par cruzado sin dólar
}
function valorPorUnidad(par, precio) {               // valor de una unidad en dólares
  if (par && par.base === 'USD') return 1;
  return precio;
}
function exposicion(simbolo, lado) {                 // compra EUR/USD = largo EUR, corto USD
  const par = partesDelPar(simbolo);
  if (!par) return {};
  const s = lado === 'VENTA' ? -1 : 1;
  return { [par.base]: s, [par.cotizada]: -s };
}

const DIAS = { Mon: 1, Tue: 2, Wed: 3, Thu: 4, Fri: 5, Sat: 6, Sun: 7 };
function enHorario(h, fecha) {
  if (h.modo === 'desactivado') return { ok: true, detalle: 'filtro horario desactivado' };
  const ventanas = h.modo === 'ny_libro' ? [['09:35', '11:15'], ['14:15', '16:00']] : h.ventanas;
  const zona = h.modo === 'ny_libro' ? 'America/New_York' : h.zona;
  const dias = h.modo === 'ny_libro' ? [1, 2, 3, 4, 5] : h.dias;
  if (!['ny_libro', 'personalizado'].includes(h.modo) || !Array.isArray(ventanas) || !Array.isArray(dias)) {
    return { ok: false, detalle: 'configuración de horario no válida: por seguridad no se opera' };
  }
  let partes;
  try {
    partes = new Intl.DateTimeFormat('en-US', { timeZone: zona, weekday: 'short', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' }).formatToParts(fecha);
  } catch (e) {
    return { ok: false, detalle: `zona horaria no válida (${zona}): por seguridad no se opera` };
  }
  const pick = t => partes.find(p => p.type === t)?.value;
  const dia = DIAS[pick('weekday')];
  const minutos = Number(pick('hour')) * 60 + Number(pick('minute'));
  const aMin = s => { const [hh, mm] = String(s).split(':').map(Number); return hh * 60 + mm; };
  const hora = `${pick('hour')}:${pick('minute')} (${zona})`;
  if (!dias.includes(dia)) return { ok: false, detalle: `fuera de los días permitidos (${hora})` };
  const dentro = ventanas.some(([a, b]) => minutos >= aMin(a) && minutos < aMin(b));
  return dentro
    ? { ok: true, detalle: `dentro de la ventana horaria (${hora})` }
    : { ok: false, detalle: `fuera de las ventanas de menor riesgo (${hora}; libro, pp. 223-224, 514-515)` };
}

// ---------- Preparación ----------
if (entrada.ok === false) {
  return [{ json: { ok: false, veredicto: 'SIN_DATOS', motivo: 'El Agente 2 no entregó una señal válida: no se opera.', errors: entrada.errors ?? [] } }];
}

const P = { ...PARAMETROS, ...(entrada.parametros ?? {}), horario: { ...PARAMETROS.horario, ...(entrada.parametros?.horario ?? {}) } };
const E = { ...ESTADO_VACIO, ...(entrada.estado ?? {}) };
for (const k of ['operacionesHoy', 'pnlHoyR', 'maxPnlHoyR', 'gananciasSeguidas', 'perdidasSeguidas', 'rachaGanadoraPrevia', 'perdidasDesdeRevision']) E[k] = aNumero(E[k], 0);
E.posiciones = Array.isArray(E.posiciones) ? E.posiciones : [];
E.ordenesPendientes = Array.isArray(E.ordenesPendientes) ? E.ordenesPendientes : [];
const ahora = entrada.ahora ? new Date(entrada.ahora) : new Date();
if (Number.isNaN(ahora.getTime())) throw new Error('El campo "ahora" no es una fecha válida.');
const capital = aNumero(entrada.cuenta?.capital, P.capitalPorDefecto);
if (!(capital > 0)) throw new Error('El capital de la cuenta debe ser mayor que cero.');

const ticker = entrada.ticker ?? null;
const d = entrada.decision ?? null;
const base = { ok: true, ticker, generadoEn: ahora.toISOString() };

if (!d) {
  return [{ json: { ...base, veredicto: 'SIN_SENAL', resumen: 'Sin señal: cero órdenes (libro, pp. 96 y 201).', motivos: [], chequeos: [], avisos: [], orden: null, diario: null } }];
}

const chequeos = [];
const avisos = [];
const revisar = (regla, ok, detalle) => chequeos.push({ regla, ok, detalle });

// 1. Ninguna orden sin entrada, stop y objetivo fijados de antemano (libro, pp. 49, 157, 160, 161, 188)
const faltan = ['entrada', 'stop', 'objetivo'].filter(k => !esNumero(d[k]));
const ordenLogico = faltan.length === 0 && d.stop > 0 && d.stop < d.entrada && d.entrada < d.objetivo;
revisar('Entrada, stop y objetivo fijados de antemano (pp. 49, 157, 160, 161, 188)', ordenLogico,
  faltan.length ? `falta: ${faltan.join(', ')}` : (ordenLogico ? 'completos y en orden (stop < entrada < objetivo)' : 'el orden stop < entrada < objetivo no se cumple'));

// 2. Datos frescos
if (esNumero(entrada.edadUltimaVelaMin)) {
  const fresco = entrada.edadUltimaVelaMin <= P.edadMaximaDatosMin;
  revisar('Datos frescos', fresco, fresco
    ? `última vela de hace ${Math.round(entrada.edadUltimaVelaMin)} min`
    : `la última vela tiene ${Math.round(entrada.edadUltimaVelaMin)} min (máximo ${P.edadMaximaDatosMin}): ¿mercado cerrado o datos atrasados?`);
} else {
  avisos.push('No se comprobó la antigüedad de los datos (falta edadUltimaVelaMin).');
}

// 3. Horario
const h = enHorario(P.horario, ahora);
revisar('Horario', h.ok, h.detalle);

// 4. Confluencias mínimas
if (P.minConfluencias > 0) {
  const ok = (d.nConfluencias ?? 0) >= P.minConfluencias;
  revisar('Confluencias mínimas', ok, `${d.nConfluencias ?? 0} de ${P.minConfluencias} requeridas`);
}

// 5. No promediar ni añadir a una posición abierta (libro, pp. 91, 104, 246)
const abiertas = [...(E.posiciones ?? []), ...(E.ordenesPendientes ?? [])];
const mismas = abiertas.filter(p => String(p.simbolo).toUpperCase() === String(ticker).toUpperCase()).length;
revisar('Una posición por símbolo (pp. 91, 104, 246)', mismas < P.maxPosicionesPorSimbolo,
  mismas < P.maxPosicionesPorSimbolo ? 'no hay otra posición en este símbolo' : `ya hay ${mismas} posición(es) u orden(es) en ${ticker}: no se añade ni se promedia`);

// 6. Máximo de posiciones abiertas
revisar('Máximo de posiciones abiertas', abiertas.length < P.maxPosicionesAbiertas,
  `${abiertas.length} abiertas o pendientes de ${P.maxPosicionesAbiertas} permitidas`);

// 7. Exposición por divisa
const cuenta = {};
for (const p of abiertas) for (const [div, s] of Object.entries(exposicion(String(p.simbolo).toUpperCase(), p.lado))) {
  cuenta[`${div}:${s}`] = (cuenta[`${div}:${s}`] ?? 0) + 1;
}
const choques = Object.entries(exposicion(String(ticker).toUpperCase(), 'COMPRA'))
  .filter(([div, s]) => (cuenta[`${div}:${s}`] ?? 0) + 1 > P.maxPosicionesPorDivisa)
  .map(([div, s]) => `${cuenta[`${div}:${s}`]} posiciones ya ${s > 0 ? 'largas' : 'cortas'} en ${div}`);
revisar('Exposición por divisa', choques.length === 0,
  choques.length ? `acumularía la misma apuesta: ${choques.join('; ')} (máximo ${P.maxPosicionesPorDivisa})` : 'la exposición por divisa queda dentro del máximo');

// 8. Operaciones del día (con reducción de frecuencia tras una racha larga, libro, p. 170)
const reducirFrecuencia = E.perdidasSeguidas >= P.perdidasParaReducirFrecuencia && E.rachaGanadoraPrevia >= P.rachaLargaMin;
const maxOps = reducirFrecuencia ? P.maxOperacionesDiaTrasRacha : P.maxOperacionesDia;
if (reducirFrecuencia) avisos.push(`${E.perdidasSeguidas} pérdidas seguidas tras una racha de ${E.rachaGanadoraPrevia} ganadoras: se baja a ${maxOps} operaciones al día (libro, p. 170).`);
revisar('Operaciones del día', E.operacionesHoy < maxOps, `${E.operacionesHoy} de ${maxOps} permitidas hoy`);

// 9. Pérdida diaria máxima
revisar('Pérdida diaria máxima', E.pnlHoyR > -P.perdidaDiariaMaxR,
  `resultado del día ${redondear(E.pnlHoyR, 2)} R (límite −${P.perdidaDiariaMaxR} R)`);

// 10. No devolver las ganancias del día (libro, p. 202)
const devuelto = E.maxPnlHoyR >= P.protegerGananciaDesdeR && E.pnlHoyR <= E.maxPnlHoyR * (1 - P.fraccionDevueltaMax);
revisar('No devolver las ganancias del día (p. 202)', !devuelto, devuelto
  ? `el día llegó a +${redondear(E.maxPnlHoyR, 2)} R y va en ${redondear(E.pnlHoyR, 2)} R: se devolvió más de ${P.fraccionDevueltaMax * 100} %`
  : `día en ${redondear(E.pnlHoyR, 2)} R (máximo ${redondear(E.maxPnlHoyR, 2)} R)`);

// 11. Revisión del diario (libro, pp. 124 y 193-195)
revisar('Revisión del diario (pp. 124, 193-195)', E.perdidasDesdeRevision < P.perdidasParaRevisar, E.perdidasDesdeRevision < P.perdidasParaRevisar
  ? `${E.perdidasDesdeRevision} pérdidas desde la última revisión`
  : `${E.perdidasDesdeRevision} pérdidas sin revisar: revisa el diario y reinicia el contador`);

// 12. Tamaño de la posición
const par = partesDelPar(ticker);
const precioActual = esNumero(entrada.precioActual) ? entrada.precioActual : d.entrada;
const precioEntrada = ordenLogico ? (d.estado === 'DISPARADA' ? Math.max(d.entrada, precioActual) : d.entrada) : null;
let tamano = null;
if (ordenLogico) {
  const distancia = precioEntrada - d.stop;
  const dolaresPorPrecio = dolaresPorUnidadYPrecio(par, precioEntrada);
  if (dolaresPorPrecio === null) {
    revisar('Tamaño de la posición', false, `par sin dólar (${ticker}): no se puede calcular el tamaño en dólares`);
  } else {
    const factor = E.gananciasSeguidas >= P.gananciasParaReducir ? P.factorTrasRacha : 1;
    if (factor < 1) avisos.push(`${E.gananciasSeguidas} ganadoras seguidas: lote a la mitad (libro, pp. 170 y 203).`);
    const riesgoObjetivo = capital * (P.riesgoPorOperacionPct / 100) * factor;
    const esCripto = par && CRIPTO.has(par.base);
    const paso = esCripto ? 1e-4 : 1;
    const piso = x => Math.floor(x / paso + 1e-9) * paso;
    let unidades = piso(riesgoObjetivo / (distancia * dolaresPorPrecio));
    let limitadoPor = factor < 1 ? 'racha' : 'riesgo';
    const maxPorNocional = piso((capital * P.nocionalMaxSobreCapital) / valorPorUnidad(par, precioEntrada));
    if (unidades > maxPorNocional) { unidades = maxPorNocional; limitadoPor = 'apalancamiento'; }
    unidades = redondear(unidades, 4);
    const riesgoDinero = unidades * distancia * dolaresPorPrecio;
    const ok = unidades >= paso;
    revisar('Tamaño de la posición', ok, ok
      ? `${unidades} unidades; riesgo ${redondear(riesgoDinero, 2)} USD (${redondear((riesgoDinero / capital) * 100, 3)} % del capital)`
      : 'el riesgo permitido no alcanza para una unidad con este stop');
    tamano = { unidades, riesgoDinero: redondear(riesgoDinero, 2), riesgoPctCapital: redondear((riesgoDinero / capital) * 100, 3),
      nocionalUSD: redondear(unidades * valorPorUnidad(par, precioEntrada), 2), limitadoPor, distancia: redondear(distancia) };
    if (limitadoPor === 'apalancamiento') avisos.push(`Tamaño recortado por el tope de ${P.nocionalMaxSobreCapital} veces el capital: el stop es muy corto.`);
  }
}

// ---------- Veredicto ----------
const motivos = chequeos.filter(c => !c.ok).map(c => c.detalle);
const aprobada = motivos.length === 0 && tamano !== null;
const veredicto = aprobada ? 'APROBADA' : 'RECHAZADA';

let orden = null;
if (aprobada) {
  const tipo = d.estado === 'DISPARADA' ? 'MERCADO' : 'STOP_PENDIENTE';
  orden = {
    simbolo: ticker, lado: 'COMPRA', tipo,
    entrada: d.entrada, precioReferencia: redondear(precioEntrada), stop: d.stop, objetivo: d.objetivo,
    unidades: tamano.unidades, riesgoDinero: tamano.riesgoDinero, riesgoPctCapital: tamano.riesgoPctCapital,
    nocionalUSD: tamano.nocionalUSD, limitadoPor: tamano.limitadoPor,
    regla: d.regla, plazo: d.plazo, metodoStop: d.metodoStop,
    gestion: {
      stopAEquilibrio: { cuando: d.breakeven, moverStopA: 'precio de entrada' },
      ventaParcial: d.ventaParcial ?? null,
      objetivo: d.objetivo,
      timeStopBarras: d.timeStopBarras ?? null
    },
    venceEnBarras: tipo === 'STOP_PENDIENTE' ? P.vencimientoOrdenBarras : null
  };
}

const resumen = aprobada
  ? `APROBADA · compra ${ticker} (${orden.tipo === 'MERCADO' ? 'a mercado' : 'orden stop pendiente'}) · entrada ${orden.entrada} · stop ${orden.stop} · objetivo ${orden.objetivo} · ${orden.unidades} unidades · riesgo ${orden.riesgoDinero} USD (${orden.riesgoPctCapital} %)`
  : `RECHAZADA · ${motivos.join('; ')}`;

const diario = {
  fecha: ahora.toISOString(), simbolo: ticker, plazo: d.plazo, lado: 'COMPRA', estadoSenal: d.estado,
  regla: d.regla, entrada: d.entrada, stop: d.stop, objetivo: d.objetivo,
  unidades: orden?.unidades ?? null, riesgoDinero: orden?.riesgoDinero ?? null,
  confluencias: d.confluencias ?? [], veredicto, motivos,
  cumpleReglas: aprobada                      // una ganancia lograda rompiendo reglas se anota como pérdida (libro, p. 173)
};

return [{ json: { ...base, veredicto, resumen, motivos, chequeos, avisos, orden, diario,
  contexto: { precioActual: redondear(precioActual), tendenciaDiaria: entrada.contextoDiario?.pendienteSMA20 ?? null } } }];

// Guarda el veredicto del Agente 3 y, si aprobó una orden, prepara la llamada que la abre.
const sd = $getWorkflowStaticData('global');
const b = sd.bandeja ?? { simbolo: null, avisos: [] };
const r3 = $input.first().json ?? {};
const mensaje = e => (typeof e === 'string' ? e : (e?.message ?? JSON.stringify(e)));

b.riesgo = r3.error ? { veredicto: 'ERROR', motivos: [`El Agente 3 falló: ${mensaje(r3.error)}`] } : r3;
sd.bandeja = b;
const hayOrden = b.riesgo.veredicto === 'APROBADA' && !!b.riesgo.orden;
return [{ json: { hayOrden, estado: sd.estado, ordenes: hayOrden ? [b.riesgo.orden] : [], velas: {} } }];

// ================================================================
// Agente 4 · Motor de paper trading (simula las operaciones, no usa dinero ni broker)
// Recibe las órdenes aprobadas por el Agente 3 y las velas nuevas, y gestiona las posiciones:
// entrada, stop, venta de la mitad, stop a equilibrio, objetivo y salida por tiempo.
// No guarda nada por sí mismo: el estado ENTRA y SALE en cada llamada (campo "estado").
// Quien lo llame (el orquestador) es quien lo guarda entre una llamada y la siguiente.
// (libro) = regla del libro "Day trading" (Vélez y Capra), con página.
// (mío)   = supuesto de simulación que debes calibrar.
//
// ENTRADA (un solo item):
//   estado       el estado devuelto por la llamada anterior (si falta, cuenta nueva)
//   ordenes      lista de "orden" aprobadas por el Agente 3 (o "orden" suelta)
//   velas        { "EUR/USD": [ {time, open, high, low, close}, ... ] }  (velas de 5 min)
//                o bien la salida del Agente 1 (ticker + candles5m)
//   ahora        fecha ISO (por defecto, ahora mismo)
//   cuenta       { capital } solo si no hay estado
//   revisionHecha  true si ya revisaste el diario (reinicia el contador de pérdidas)
//   parametros   cualquier parámetro de abajo
// ================================================================

const entrada = $input.first().json ?? {};

// ---------- PARÁMETROS: puedes editarlos aquí ----------
const PARAMETROS = {
  capitalPorDefecto: 10000,                // (mío) cuenta de prueba en dólares
  barraDatosMin: 5,                        // (mío) minutos de cada vela con que se gestionan las posiciones
  minutosPorPlazo: { '5min': 5, '15min': 15, '1h': 60, '1day': 1440 },
  neutralR: 0.05,                          // (mío) una operación entre -0,05 R y +0,05 R no cuenta como racha
  zonaDia: 'UTC',                          // (mío) zona que define cuándo empieza el día para los contadores diarios
  friccionPct: { forex: 0.006, cripto: 0.2, otros: 0.02 },   // (mío) costo de ida y vuelta, % del valor de la posición
  maxFilasDiario: 200
};

// Reglas de la simulación (todas pesimistas, para no ser optimista por accidente):
//  - Solo se usan velas CERRADAS. La vela en curso se procesa cuando cierre.
//  - Si en una misma vela el precio toca el stop y también un nivel a favor, se asume que tocó el stop primero.
//  - Si una vela abre más allá del stop, la salida es al precio de apertura (hueco), no al stop.
//  - Tras vender la mitad y subir el stop a equilibrio, si esa misma vela vuelve al precio de entrada, se asume que salió ahí.
//  - Una orden a mercado entra al precio de referencia; una orden pendiente entra al precio de la orden (o a la apertura si hay hueco).
//  - La posición se gestiona desde la primera vela que abre después de la entrada.

// ---------- Utilidades ----------
const CRIPTO = new Set(['BTC', 'ETH', 'SOL', 'XRP', 'LTC', 'BNB', 'ADA', 'DOGE']);
const redondear = (x, d = 8) => (Number.isFinite(x) ? Math.round(x * 10 ** d) / 10 ** d : null);
const esNumero = x => typeof x === 'number' && Number.isFinite(x);
const num = (x, def) => (x !== null && x !== '' && x !== undefined && Number.isFinite(Number(x)) ? Number(x) : def);
const arreglo = x => (Array.isArray(x) ? x : []);
const iso = ms => new Date(ms).toISOString();
const mayus = s => String(s ?? '').toUpperCase();

function partesDelPar(simbolo) {
  const m = /^([A-Z]{3,5})\/([A-Z]{3,5})$/.exec(mayus(simbolo));
  return m ? { base: m[1], cotizada: m[2] } : null;
}
const claseActivo = s => { const p = partesDelPar(s); return p ? (CRIPTO.has(p.base) ? 'cripto' : 'forex') : 'otros'; };
const pasoUnidades = s => (claseActivo(s) === 'cripto' ? 1e-4 : 1);

// ---------- Preparación ----------
const P = { ...PARAMETROS, ...(entrada.parametros ?? {}), friccionPct: { ...PARAMETROS.friccionPct, ...(entrada.parametros?.friccionPct ?? {}) } };
const ahora = entrada.ahora ? new Date(entrada.ahora) : new Date();
if (Number.isNaN(ahora.getTime())) throw new Error('El campo "ahora" no es una fecha válida.');
const ahoraMs = ahora.getTime();
const barraMs = P.barraDatosMin * 60000;

const E0 = JSON.parse(JSON.stringify(entrada.estado ?? {}));
const E = {
  capital: num(E0.capital, num(entrada.cuenta?.capital, P.capitalPorDefecto)),
  posiciones: arreglo(E0.posiciones),
  ordenesPendientes: arreglo(E0.ordenesPendientes),
  ultimaVela: E0.ultimaVela && typeof E0.ultimaVela === 'object' ? E0.ultimaVela : {},
  dia: E0.dia ?? null,
  operacionesHoy: num(E0.operacionesHoy, 0), pnlHoyR: num(E0.pnlHoyR, 0), maxPnlHoyR: num(E0.maxPnlHoyR, 0),
  gananciasSeguidas: num(E0.gananciasSeguidas, 0), perdidasSeguidas: num(E0.perdidasSeguidas, 0),
  rachaGanadoraPrevia: num(E0.rachaGanadoraPrevia, 0), perdidasDesdeRevision: num(E0.perdidasDesdeRevision, 0),
  siguienteId: num(E0.siguienteId, 1),
  diario: arreglo(E0.diario)
};
if (!(E.capital > 0)) throw new Error('El capital debe ser mayor que cero.');

let formatoDia;
try {
  formatoDia = new Intl.DateTimeFormat('en-CA', { timeZone: P.zonaDia, year: 'numeric', month: '2-digit', day: '2-digit' });
  formatoDia.format(ahora);
} catch (e) { throw new Error(`Zona horaria no válida: ${P.zonaDia}`); }
const diaDe = ms => formatoDia.format(new Date(ms));
// Día nuevo: se reinician los contadores diarios (las rachas siguen).
// El día de cada hecho es el de su vela, no el de la llamada: así partir las velas en varias llamadas da lo mismo.
function avanzarDia(ms) {
  const k = diaDe(ms);
  if (k > E.dia) { E.dia = k; E.operacionesHoy = 0; E.pnlHoyR = 0; E.maxPnlHoyR = 0; }
}
if (E.dia === null) E.dia = diaDe(ahoraMs);
if (entrada.revisionHecha === true) E.perdidasDesdeRevision = 0;

const eventos = [], diarioNuevo = [], avisos = [];

// Velas por símbolo: solo cerradas, ordenadas, sin datos inválidos
function limpiar(v) {
  return arreglo(v).map(c => ({ ...c, t: Date.parse(c.time), open: Number(c.open), high: Number(c.high), low: Number(c.low), close: Number(c.close) }))
    .filter(c => Number.isFinite(c.t) && [c.open, c.high, c.low, c.close].every(Number.isFinite) && c.high >= c.low)
    .sort((a, b) => a.t - b.t);
}
const velasPorSimbolo = {};
if (entrada.velas && typeof entrada.velas === 'object') for (const [s, v] of Object.entries(entrada.velas)) velasPorSimbolo[mayus(s)] = limpiar(v);
if (entrada.ticker && Array.isArray(entrada.candles5m) && !velasPorSimbolo[mayus(entrada.ticker)]) velasPorSimbolo[mayus(entrada.ticker)] = limpiar(entrada.candles5m);

// ---------- Contabilidad ----------
function pnlBruto(pos, precio, unidades) {
  const par = partesDelPar(pos.simbolo);
  const dif = precio - pos.entrada;                                  // solo posiciones largas
  return par && par.base === 'USD' ? (dif * unidades) / precio : dif * unidades;
}
function friccion(pos, unidades) {
  const par = partesDelPar(pos.simbolo);
  const valor = par && par.base === 'USD' ? unidades : unidades * pos.entrada;
  return valor * (P.friccionPct[claseActivo(pos.simbolo)] ?? P.friccionPct.otros) / 100;
}

function cerrarParte(pos, precio, unidades, tipo, tms) {
  const costo = friccion(pos, unidades);
  const pnl = pnlBruto(pos, precio, unidades) - costo;
  pos.realizadoUSD = pos.realizadoUSD + pnl;
  pos.unidadesRestantes = redondear(pos.unidadesRestantes - unidades, 6);
  E.capital = redondear(E.capital + pnl, 6);
  eventos.push({ tipo, id: pos.id, simbolo: pos.simbolo, tiempo: iso(tms), precio: redondear(precio), unidades: redondear(unidades, 6),
    pnlUSD: redondear(pnl, 6), costoUSD: redondear(costo, 6) });
}

function cerrarTodo(pos, precio, tipo, tms) {
  cerrarParte(pos, precio, pos.unidadesRestantes, tipo, tms);
  avanzarDia(tms);
  const R = pos.riesgoDinero > 0 ? pos.realizadoUSD / pos.riesgoDinero : 0;
  E.pnlHoyR += R; E.maxPnlHoyR = Math.max(E.maxPnlHoyR, E.pnlHoyR);
  if (R > P.neutralR) {
    E.gananciasSeguidas += 1; E.perdidasSeguidas = 0; E.rachaGanadoraPrevia = 0;
  } else if (R < -P.neutralR) {
    if (E.perdidasSeguidas === 0) E.rachaGanadoraPrevia = E.gananciasSeguidas;
    E.gananciasSeguidas = 0; E.perdidasSeguidas += 1; E.perdidasDesdeRevision += 1;
  }
  const fila = {
    id: pos.id, simbolo: pos.simbolo, plazo: pos.plazo, lado: 'COMPRA', regla: pos.regla,
    apertura: pos.abiertaEn, cierre: iso(tms), duracionMin: Math.round((tms - Date.parse(pos.abiertaEn)) / 60000),
    entrada: pos.entrada, stopInicial: pos.stopInicial, objetivo: pos.objetivo, salidaFinal: redondear(precio),
    unidades: pos.unidades, motivoSalida: tipo, pnlUSD: redondear(pos.realizadoUSD, 4), R: redondear(R, 3),
    cumpleReglas: true                       // el motor solo ejecuta lo que el Agente 3 aprobó (libro, p. 173)
  };
  diarioNuevo.push(fila);
  E.diario.push(fila);
  if (E.diario.length > P.maxFilasDiario) E.diario.splice(0, E.diario.length - P.maxFilasDiario);
  E.posiciones = E.posiciones.filter(p => p.id !== pos.id);
}

// ---------- Gestión de una vela cerrada ----------
function unidadesParciales(pos) {
  const paso = pasoUnidades(pos.simbolo), f = pos.ventaParcial?.fraccion ?? 0;
  const u = Math.floor((pos.unidades * f) / paso + 1e-9) * paso;
  return u >= paso && u < pos.unidadesRestantes ? redondear(u, 4) : 0;
}

function gestionarBarra(pos, b) {
  pos.ultimaBarraGestionada = b.t;
  // 1. Stop (el stop solo sube, nunca se aleja: libro, pp. 157, 179)
  if (b.low <= pos.stop) {
    return cerrarTodo(pos, Math.min(pos.stop, b.open), pos.stopEnEquilibrio ? 'STOP_EQUILIBRIO' : 'STOP', b.t);
  }
  // 2. Venta de la mitad y stop a equilibrio (libro, pp. 431-433, 438-441)
  const nivel = pos.ventaParcial?.en ?? pos.nivelEquilibrio;
  if (!pos.parcialHecha && esNumero(nivel) && b.high >= nivel) {
    pos.parcialHecha = true;
    const vender = unidadesParciales(pos);
    if (vender > 0) cerrarParte(pos, Math.max(nivel, b.open), vender, 'PARCIAL', b.t);
    if (pos.entrada > pos.stop) {
      pos.stop = pos.entrada; pos.stopEnEquilibrio = true;
      eventos.push({ tipo: 'STOP_A_EQUILIBRIO', id: pos.id, simbolo: pos.simbolo, tiempo: iso(b.t), precio: redondear(pos.stop) });
    }
    if (b.low <= pos.stop) return cerrarTodo(pos, pos.stop, 'STOP_EQUILIBRIO', b.t);
  }
  // 3. Objetivo
  if (b.high >= pos.objetivo) return cerrarTodo(pos, Math.max(pos.objetivo, b.open), 'OBJETIVO', b.t);
  // 4. Salida por tiempo (libro, p. 436)
  const plazoMs = (P.minutosPorPlazo[pos.plazo] ?? P.barraDatosMin) * 60000;
  if (pos.timeStopBarras && (b.t + barraMs) - Date.parse(pos.abiertaEn) >= pos.timeStopBarras * plazoMs) {
    return cerrarTodo(pos, b.close, 'TIEMPO', b.t + barraMs);
  }
}

function abrirPosicion(o, precio, tms, detalle) {
  const pos = {
    id: `T${E.siguienteId++}`, simbolo: mayus(o.simbolo), plazo: o.plazo ?? null, lado: 'COMPRA',
    unidades: o.unidades, unidadesRestantes: o.unidades,
    entrada: redondear(precio), entradaPlan: o.entrada, stop: o.stop, stopInicial: o.stop, objetivo: o.objetivo,
    ventaParcial: o.gestion?.ventaParcial ?? null, nivelEquilibrio: o.gestion?.stopAEquilibrio?.cuando ?? null,
    parcialHecha: false, stopEnEquilibrio: false, timeStopBarras: o.gestion?.timeStopBarras ?? null,
    abiertaEn: iso(tms), regla: o.regla ?? null, metodoStop: o.metodoStop ?? null,
    riesgoDinero: o.riesgoDinero, realizadoUSD: 0, ultimaBarraGestionada: null
  };
  E.posiciones.push(pos);
  avanzarDia(tms);
  E.operacionesHoy += 1;
  eventos.push({ tipo: 'ENTRADA', id: pos.id, simbolo: pos.simbolo, tiempo: iso(tms), precio: pos.entrada, unidades: pos.unidades, detalle });
  return pos;
}

// ---------- 1) Velas cerradas desde la última llamada (en orden cronológico entre todos los símbolos) ----------
const trabajo = [];
for (const [sim, velas] of Object.entries(velasPorSimbolo)) {
  const ult = E.ultimaVela[sim] ? Date.parse(E.ultimaVela[sim]) : -Infinity;
  const nuevas = velas.filter(b => b.t > ult && b.t + barraMs <= ahoraMs);
  for (const b of nuevas) trabajo.push({ sim, b });
  if (nuevas.length) E.ultimaVela[sim] = iso(nuevas.at(-1).t);
}
trabajo.sort((x, y) => x.b.t - y.b.t || (x.sim < y.sim ? -1 : 1));
for (const { sim, b } of trabajo) {
  for (const ord of E.ordenesPendientes.filter(o => o.simbolo === sim)) {
    if (b.t >= Date.parse(ord.venceEn)) {
      E.ordenesPendientes = E.ordenesPendientes.filter(o => o.id !== ord.id);
      eventos.push({ tipo: 'ORDEN_VENCIDA', id: ord.id, simbolo: sim, tiempo: iso(b.t), detalle: 'no se activó a tiempo' });
    } else if (b.t >= Date.parse(ord.creadaEn) && b.high >= ord.entrada) {
      E.ordenesPendientes = E.ordenesPendientes.filter(o => o.id !== ord.id);
      const pos = abrirPosicion(ord, Math.max(ord.entrada, b.open), b.t, 'orden stop activada');
      gestionarBarra(pos, b);
    }
  }
  for (const pos of [...E.posiciones.filter(p => p.simbolo === sim)]) {
    if (b.t >= Date.parse(pos.abiertaEn) && !(pos.ultimaBarraGestionada >= b.t)) gestionarBarra(pos, b);
  }
}
for (const s of new Set([...E.posiciones, ...E.ordenesPendientes].map(x => x.simbolo))) {
  if (!velasPorSimbolo[s]) avisos.push(`No llegaron velas de ${s}: su posición u orden no se gestionó en esta llamada.`);
}

// ---------- 2) Órdenes nuevas del Agente 3 ----------
const nuevasOrdenes = [...arreglo(entrada.ordenes), ...(entrada.orden ? [entrada.orden] : [])];
for (const o of nuevasOrdenes) {
  const sim = mayus(o?.simbolo);
  const rechazar = detalle => eventos.push({ tipo: 'ORDEN_RECHAZADA', simbolo: sim || null, tiempo: iso(ahoraMs), detalle });
  const faltan = ['entrada', 'stop', 'objetivo', 'unidades', 'riesgoDinero'].filter(k => !esNumero(o?.[k]));
  if (!sim || faltan.length) { rechazar(`orden incompleta (falta: ${faltan.join(', ') || 'símbolo'})`); continue; }
  if (!(o.stop > 0 && o.stop < o.entrada && o.entrada < o.objetivo && o.unidades > 0)) { rechazar('orden con precios o unidades sin sentido'); continue; }
  if ([...E.posiciones, ...E.ordenesPendientes].some(x => x.simbolo === sim)) { rechazar('ya hay una posición u orden en este símbolo (no se promedia)'); continue; }
  if (o.tipo === 'MERCADO') {
    const precio = esNumero(o.precioReferencia) ? o.precioReferencia : o.entrada;
    if (precio <= o.stop) { rechazar('el precio actual ya está por debajo del stop'); continue; }
    abrirPosicion(o, precio, ahoraMs, 'a mercado');
  } else if (o.tipo === 'STOP_PENDIENTE') {
    const plazoMs = (P.minutosPorPlazo[o.plazo] ?? P.barraDatosMin) * 60000;
    const id = `T${E.siguienteId++}`;
    E.ordenesPendientes.push({ ...o, id, simbolo: sim, creadaEn: iso(ahoraMs), venceEn: iso(ahoraMs + (o.venceEnBarras ?? 3) * plazoMs) });
    eventos.push({ tipo: 'ORDEN_PENDIENTE', id, simbolo: sim, tiempo: iso(ahoraMs), precio: o.entrada, unidades: o.unidades, detalle: 'espera a que el precio supere la entrada' });
  } else {
    rechazar(`tipo de orden desconocido (${o.tipo})`);
  }
}

// ---------- Salida ----------
avanzarDia(ahoraMs);
E.capital = redondear(E.capital, 6);
const ultimoPrecio = s => velasPorSimbolo[s]?.at(-1)?.close ?? null;
const abiertas = E.posiciones.map(p => {
  const px = ultimoPrecio(p.simbolo);
  return { id: p.id, simbolo: p.simbolo, entrada: p.entrada, stop: p.stop, objetivo: p.objetivo, unidadesRestantes: p.unidadesRestantes,
    parcialHecha: p.parcialHecha, stopEnEquilibrio: p.stopEnEquilibrio, abiertaEn: p.abiertaEn,
    pnlNoRealizadoUSD: px === null ? null : redondear(pnlBruto(p, px, p.unidadesRestantes), 4) };
});
const pendientes = E.ordenesPendientes.map(o => ({ id: o.id, simbolo: o.simbolo, entrada: o.entrada, venceEn: o.venceEn }));

const lineas = eventos.map(e => `${e.tipo} ${e.simbolo ?? ''}${e.precio !== undefined ? ' @' + e.precio : ''}${e.pnlUSD !== undefined ? ` (${e.pnlUSD >= 0 ? '+' : ''}${e.pnlUSD} USD)` : ''}${e.tipo === 'ORDEN_RECHAZADA' ? ': ' + e.detalle : ''}`);
const resumen = `${eventos.length ? lineas.join(' · ') : 'Sin eventos.'} | capital ${E.capital} USD | abiertas ${abiertas.length} | pendientes ${pendientes.length} | día: ${E.operacionesHoy} entradas, ${redondear(E.pnlHoyR, 2)} R`;

return [{ json: { ok: true, generadoEn: iso(ahoraMs), resumen, eventos, diarioNuevo, abiertas, pendientes, avisos, estado: E } }];

// Cierra el par: guarda el estado final, resume lo ocurrido y vacía la bandeja.
const sd = $getWorkflowStaticData('global');
const b = sd.bandeja ?? { simbolo: null, avisos: [] };
const x = $input.first().json ?? {};
const mensaje = e => (typeof e === 'string' ? e : (e?.message ?? JSON.stringify(e)));

const eventos = [...(b.eventosGestion ?? [])];
if (x.error) {
  b.avisos.push(`Falló al abrir la orden: ${mensaje(x.error)}`);
} else if (Array.isArray(x.eventos)) {          // salida del Agente 4 al abrir la orden
  sd.estado = x.estado;
  eventos.push(...x.eventos);
}

const senal = b.senal ?? {};
const rg = b.riesgo ?? {};
const texto = e => `${e.tipo}${e.precio !== undefined ? ' @' + e.precio : ''}${e.pnlUSD !== undefined ? ` (${e.pnlUSD >= 0 ? '+' : ''}${e.pnlUSD} USD)` : ''}${e.tipo === 'ORDEN_RECHAZADA' ? ': ' + e.detalle : ''}`;

const fila = {
  simbolo: b.simbolo,
  datosOk: b.datos?.ok ?? false,
  precio: senal.precioActual ?? null,
  tendenciaDiaria: senal.contextoDiario?.pendienteSMA20 ?? null,
  edadUltimaVelaMin: b.edadUltimaVelaMin ?? null,
  senal: senal.resumen ?? senal.motivo ?? null,
  veredicto: rg.veredicto ?? null,
  motivos: rg.motivos ?? [],
  eventos: eventos.map(texto),
  avisos: [...b.avisos, ...(b.datos?.errores ?? []), ...(rg.avisos ?? [])]
};
sd.bandeja = null;
return [{ json: fila }];

// Junta todos los pares de la pasada y muestra el estado de la cuenta de prueba.
const sd = $getWorkflowStaticData('global');
const filas = $input.all().map(i => i.json);
const est = sd.estado ?? {};
const VIEJA_MIN = 15;

const sinDatos = filas.filter(f => !f.datosOk);
const viejos = filas.filter(f => f.datosOk && typeof f.edadUltimaVelaMin === 'number' && f.edadUltimaVelaMin > VIEJA_MIN).map(f => `${f.simbolo} (última vela de hace ${Math.round(f.edadUltimaVelaMin)} min)`);
const movimientos = filas.flatMap(f => f.eventos.map(e => `${f.simbolo}: ${e}`));
const rechazadas = filas.filter(f => f.veredicto === 'RECHAZADA').map(f => `${f.simbolo}: ${f.motivos.join('; ')}`);
const sinSenal = filas.filter(f => f.datosOk && f.veredicto === 'SIN_SENAL').map(f => `${f.simbolo} (tendencia diaria ${f.tendenciaDiaria ?? '?'})`);
const sinGestionar = [...(est.posiciones ?? []), ...(est.ordenesPendientes ?? [])]
  .filter(p => !filas.some(f => f.simbolo === p.simbolo)).map(p => p.simbolo);

sd.bandeja = null;
return [{ json: {
  pasadaNumero: sd.meta?.pasadas ?? null,
  pares: filas.length,
  movimientos,
  rechazadas,
  sinSenal,
  conProblemas: sinDatos.map(f => `${f.simbolo ?? '?'}: ${f.senal ?? 'sin datos'} ${f.avisos.length ? '· ' + f.avisos.join(' | ') : ''}`.trim()),
  datosViejos: viejos,
  avisos: [
    ...(sinGestionar.length ? [`Hay posiciones u órdenes en pares que ya no están en la lista y no se gestionan: ${[...new Set(sinGestionar)].join(', ')}`] : []),
    ...((est.perdidasDesdeRevision ?? 0) >= 5 ? [`Hay ${est.perdidasDesdeRevision} pérdidas sin revisar: el Agente 3 no abrirá operaciones nuevas hasta que revises el diario (mira "ultimasOperaciones"). Cuando lo hayas hecho, pon REVISION_DEL_DIARIO_HECHA = true en "Preparar pasada", ejecuta una vez y vuelve a ponerlo en false.`] : [])
  ],
  cuenta: {
    capital: est.capital ?? null,
    operacionesHoy: est.operacionesHoy ?? 0, resultadoHoyR: est.pnlHoyR ?? 0,
    gananciasSeguidas: est.gananciasSeguidas ?? 0, perdidasSeguidas: est.perdidasSeguidas ?? 0, perdidasSinRevisar: est.perdidasDesdeRevision ?? 0,
    abiertas: (est.posiciones ?? []).map(p => ({ id: p.id, simbolo: p.simbolo, entrada: p.entrada, stop: p.stop, objetivo: p.objetivo, unidadesRestantes: p.unidadesRestantes, parcialHecha: p.parcialHecha })),
    pendientes: (est.ordenesPendientes ?? []).map(o => ({ id: o.id, simbolo: o.simbolo, entrada: o.entrada, venceEn: o.venceEn }))
  },
  ultimasOperaciones: (est.diario ?? []).slice(-5),
  detalle: filas
} }];
